<?php
declare(strict_types=1);
require __DIR__.'/../../app/bootstrap.php';
require_login();
$pdo=db();
$pdo->exec("CREATE TABLE IF NOT EXISTS orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,total DECIMAL(12,2) NOT NULL DEFAULT 0.00,delivery_method VARCHAR(40) NOT NULL,delivery_at DATETIME NOT NULL,address TEXT NOT NULL,recipient_name VARCHAR(160) NOT NULL,recipient_phone VARCHAR(20) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'new',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_orders_user(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
$pdo->exec("CREATE TABLE IF NOT EXISTS order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,product_name VARCHAR(200) NOT NULL,quantity INT UNSIGNED NOT NULL,unit_price DECIMAL(12,2) NOT NULL DEFAULT 0.00,INDEX idx_order_items_order(order_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'');if(!in_array($status,['new','processing','delivered','cancelled'],true))$error='وضعیت انتخاب‌شده معتبر نیست.';else{$s=$pdo->prepare('UPDATE orders SET status=? WHERE id=?');$s->execute([$status,$id]);notice('وضعیت سفارش ذخیره شد.');go('orders.php');}}
$rows=$pdo->query('SELECT * FROM orders ORDER BY id DESC')->fetchAll();
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>سفارش‌ها · مدیریت</title><link rel="stylesheet" href="../assets/admin.css"><style>.order-meta{color:#6d7f90;font-size:12px;line-height:1.9}.order-form{display:flex;gap:6px;align-items:center;min-width:180px}.order-form select{max-width:140px}</style></head><body><div class="layout"><aside class="sidebar"><a class="brand" href="index.php"><span class="logo mini">K</span><span><b>Kadad CMS</b><small>مدیریت سایت</small></span></a><p class="nav-label">مدیریت</p><a class="nav" href="index.php">▦ <span>نمای کلی</span></a><a class="nav" href="index.php?page=products">◇ <span>محصولات</span></a><a class="nav active" href="orders.php">▤ <span>سفارش‌ها</span></a><a class="nav" href="index.php?page=accounts">♙ <span>حساب‌های مدیریت</span></a><a class="nav" href="index.php?page=settings">⚙ <span>تنظیمات سایت</span></a></aside><main class="main"><header class="topbar"><div><small class="eyebrow">فروشگاه</small><h1>سفارش‌ها</h1></div><a class="button secondary" href="../">مشاهده سایت ↗</a></header><section class="content"><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><?php $notice=(string)($_SESSION['_notice']??'');unset($_SESSION['_notice']);if($notice):?><div class="alert"><?=e($notice)?></div><?php endif;?><section class="panel"><div class="panel-head"><div><h3>سفارش‌های فروشگاه</h3><p>مبلغ همهٔ سفارش‌ها فعلاً ۰ تومان است.</p></div></div><?php if(!$rows):?><div class="empty"><b>هنوز سفارشی ثبت نشده</b><p>سفارش‌های جدید در این صفحه نمایش داده می‌شوند.</p></div><?php else:?><div class="table-wrap"><table><thead><tr><th>سفارش</th><th>تحویل‌گیرنده</th><th>محصولات</th><th>آدرس و نحوه تحویل</th><th>زمان تحویل</th><th>مبلغ</th><th>وضعیت</th></tr></thead><tbody><?php foreach($rows as $r):$s=$pdo->prepare('SELECT product_name,quantity FROM order_items WHERE order_id=?');$s->execute([(int)$r['id']]);$items=$s->fetchAll();?><tr><td><b>#<?=(int)$r['id']?></b><small class="order-meta" style="display:block"><?=e($r['created_at'])?></small></td><td><?=e($r['recipient_name'])?><small class="order-meta" style="display:block"><?=e($r['recipient_phone'])?></small></td><td><?php foreach($items as $it):?><div><?=e($it['product_name'])?> × <?=(int)$it['quantity']?></div><?php endforeach;?></td><td><?=e(['courier'=>'ارسال به آدرس','pickup'=>'تحویل حضوری','digital'=>'دیجیتال / آنلاین'][$r['delivery_method']]??$r['delivery_method'])?><small class="order-meta" style="display:block"><?=e($r['address'])?></small></td><td><?=e($r['delivery_at'])?></td><td>۰ تومان</td><td><form method="post" class="order-form"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><select name="status"><option value="new" <?=$r['status']==='new'?'selected':''?>>ثبت‌شده</option><option value="processing" <?=$r['status']==='processing'?'selected':''?>>در حال آماده‌سازی</option><option value="delivered" <?=$r['status']==='delivered'?'selected':''?>>تحویل‌شده</option><option value="cancelled" <?=$r['status']==='cancelled'?'selected':''?>>لغوشده</option></select><button class="button primary">ذخیره</button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><footer>Kadad CMS · مدیریت سفارش‌ها</footer></section></main></div></body></html>